<x-dashboard-layout title="Activity"><div class="operations-page"><div class="page-heading"><div><p class="breadcrumb">Workspace / Activity</p><h1>Activity history</h1><p>An audit trail of infrastructure and workspace changes.</p></div></div><section class="card activity-page-card"><div class="card-head"><div><h2>Workspace events</h2><p>User, resource, result, address, and timestamp.</p></div><form class="search-filter-form"><div class="table-search"><i data-lucide="search"></i><input name="search" value="{{ request('search') }}" placeholder="Search activity..."></div><select name="status" onchange="this.form.submit()"><option value="">All statuses</option><option value="success">Success</option><option value="failed">Failed</option></select></form></div><div class="activity-head"><span>Event</span><span>User</span><span>Resource</span><span>IP address</span><span>Status</span><span>Timestamp</span></div>@foreach($activities as $activity)<div class="activity-page-row"><span class="resource-primary"><span class="activity-symbol"><i data-lucide="{{ str_contains($activity->action,'backup')?'archive':(str_contains($activity->action,'domain')?'globe-2':(str_contains($activity->action,'server')?'server':'activity')) }}"></i></span><span><strong>{{ $activity->description }}</strong><small>{{ $activity->action }}</small></span></span><span>{{ $activity->user?->name??'System' }}</span><span>{{ $activity->subject_type?class_basename($activity->subject_type).' #'.$activity->subject_id:'Workspace' }}</span><span class="mono">{{ $activity->ip_address??'Internal' }}</span><span><em class="status status--{{ $activity->status==='failed'?'failed':'success' }}"><i></i>{{ ucfirst($activity->status??'success') }}</em></span><span>{{ $activity->created_at->format('M j, Y H:i') }}</span></div>@endforeach<div class="pagination-wrap">{{ $activities->links() }}</div></section></div></x-dashboard-layout>
